    var commentCmds = st.commands.filter(function (c) { return c.indexOf('issue comment') !== -1; });
    var bodyPath = commentCmds[0].replace(/^.*--body-file '/, '').replace(/'$/, '');
    assert.ok(io.written[bodyPath].indexOf('thread summary') === -1);
