            java.lang.System && typeof java.lang.System.getenv === 'function') {
            var v = java.lang.System.getenv(name);
            return (v === null || v === undefined) ? '' : String(v);
        }
    } catch (e) { /* no env bridge on this runtime */ }
    return '';
