/**
 * JSRunner entry — apply the review verdict (review runs only). Thin caller
 * for js/factory/review_verdict.js, the JS port of the awf
 * factory-teammate.yml «Apply the review verdict» step
 * (IstiN/dmtools-agentic-workflows#34 scripts/apply-review-verdict.sh).
 *
 * Invocation (machine-kit / final awf rewire — the sh call becomes):
 *   dmtools run agents/js/factory/run_review_verdict.json
 *
 * Params resolve customParams first, then the sh step's env names, then the
 * sh defaults. See js/factory/README.md for the full env/file contract.
 *
 * Error contract mirrors the sh under `bash -e`: the loud no-verdict path
 * (gh-305) THROWS after leaving needs-human + the diagnosis comment (the sh
 * exits 1 — the step must redden); the parser-invocation transport is
 * unwrapped ((res.output || res.stdout) || res — the #893 review lesson)
 * and never trimmed.
 */

var reviewVerdict = require('./review_verdict.js');

/**
 * Env reader for the fallback path (guarded — no java bridge on QuickJS).
 */
function envValue(name) {
    try {
        if (typeof java !== 'undefined' && java && java.lang &&
            java.lang.System && typeof java.lang.System.getenv === 'function') {
            var v = java.lang.System.getenv(name);
            return (v === null || v === undefined) ? '' : String(v);
        }
    } catch (e) { /* no env bridge on this runtime */ }
    return '';
}

/**
 * customParams > env > sh-step defaults. envMap is a test seam.
 */
function resolveParams(params, envMap) {
    var custom = (params && params.jobParams && params.jobParams.customParams) || {};
    function env(name) {
        if (envMap && Object.prototype.hasOwnProperty.call(envMap, name)) return envMap[name];
        return envValue(name);
    }
    function pick(key, envName, dflt) {
        var v = custom[key];
        if (v === undefined || v === null || v === '') v = env(envName);
        if (v === undefined || v === null || v === '') v = dflt;
        return v === undefined || v === null ? '' : String(v);
    }
    var tmpSeq = 0;
    return {
        repo: pick('repo', 'GITHUB_REPOSITORY', ''),
        number: pick('number', 'NUMBER', ''),
        runOutput: pick('runOutput', 'RUN_OUTPUT', reviewVerdict.DEFAULT_RUN_OUTPUT || '.dmtools/run-output.txt'),
        machineAuthor: pick('machineAuthor', 'MACHINE_AUTHOR', ''),
        maxRounds: pick('maxRounds', 'MAX_ROUNDS', ''),
        config: pick('config', 'CONFIG', ''),
        factoryRoot: pick('factoryRoot', 'FACTORY_ROOT', ''),
        home: pick('home', 'HOME', ''),
        ghToken: pick('ghToken', 'GH_TOKEN', ''),
        _tmpSeq: function () { return ++tmpSeq; }
    };
}

/**
 * JSRunner action. deps is a test seam: production resolves the dmtools
 * globals (cli_execute_command / file_write / file_read). The no-verdict
 * path throws (exit-1 parity — the workflow step must redden); every other
 * terminal state returns { status, ... }.
 */
function action(params, deps) {
    deps = deps || {};
    var exec = deps.cli_execute_command ||
        (typeof cli_execute_command === 'function' ? cli_execute_command : null);
    var writeRaw = deps.file_write ||
        (typeof file_write === 'function' ? file_write : null);
    var readRaw = deps.file_read ||
        (typeof file_read === 'function' ? file_read : null);
    var opts = resolveParams(params, deps.env);
    var seq = opts._tmpSeq;
    delete opts._tmpSeq;
    var result = reviewVerdict.applyReviewVerdict(opts, {
        exec: function (cmd) {
            var res = exec({ command: cmd });
            // execOut pattern, no trim: bodies/file paths ride verbatim.
            // An empty-output result object is an empty output — never the
            // object itself ('[object Object]' as a command string).
            var out = res && (res.output || res.stdout);
            if (out === undefined || out === null) {
                out = (typeof res === 'string') ? res : '';
            }
            return String(out || '');
        },
        writeFile: function (p, c) {
            if (!writeRaw) throw new Error('file_write is not available on this runtime');
            return writeRaw(p, c);
        },
        readFile: function (p) {
            if (!readRaw) throw new Error('file_read is not available on this runtime');
            return readRaw({ path: p });
        },
        tempFile: function (hint) {
            var base = (opts.runOutput && opts.runOutput.indexOf('/') === 0)
                ? opts.runOutput.replace(/[^/]*$/, '') : '/tmp/';
            return base + 'rv-' + seq() + '-' + hint;
        },
        clock: deps.clock || function () { return new Date(); },
        sleepMs: deps.sleepMs || function (ms) { /* the runtime's own timer would go here */ },
        log: deps.console_log ||
            (typeof console_log === 'function' ? console_log : function (line) { console.log(line); })
    });
    console.log('  ⚖️ review verdict: ' + result.status +
        (result.pr ? ' (PR #' + result.pr + ')' : '') +
        (result.decision ? ' — ' + result.decision : ''));
    return result;
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        action: action,
        resolveParams: resolveParams,
        envValue: envValue
    };
}

/**
 * Factory review verdict — the zero-maintainer keystone glue (owner
 * directive 2026-10-13: factory glue moves into dmtools-agents as JS agent
 * code; awf workflows become thin callers).
 *
 * JS port of the awf factory-teammate.yml step «Apply the review verdict
 * (review runs only)» — byte-extracted into scripts/apply-review-verdict.sh
 * by IstiN/dmtools-agentic-workflows#34. Behavior contract is identical:
 *
 *   1. GH_TOKEN missing → warn + skip (labels would not trigger workflows).
 *   2. Fallback sources: the issue's labels, the linked open PR (closes/
 *      fixes/resolves #N in the body, or headRefName ^N[-_.] / gh-0*N$),
 *      the PR's comments+reviews and the issue's comments (a failed fetch
 *      leaves the source file absent — the parser reports `missing`).
 *   3. machineAuthor: workflow input first, then the per-repo
 *      .dmtools/config.js knob (js/common/machineAuthor.js order #2).
 *   4. Parser selection: the unpacked pack's loop/verdict.sh WINS
 *      (versions with the reviewed pack); the legacy
 *      ${FACTORY_ROOT}/setup/review-verdict.sh is the old-pin fallback.
 *   5. The parser emits an eval-safe key=value contract (decision, source,
 *      override, blocking_markers, rounds_done, next_round, escalate,
 *      round_labels, diagnosis). JS parses it line-wise instead of eval'ing
 *      — conformant contracts parse identically; non-conformant output is
 *      IGNORED rather than executed (deliberate hardening, documented).
 *   6. rework + escalate → strip round labels, needs-human (B60205), the
 *      GraphQL review-threads summary comment, done. rework → remove
 *      needs-human, agent:rework + rework-round-N (BFD4F2). approve → the
 *      CI-green gate (≤10 min of 30s polls; red checks refuse the verdict;
 *      all-green → strip labels, pr_approved). No verdict at all → LOUD
 *      failure (gh-305): ::error:: annotation, needs-human, per-source
 *      diagnosis comment, THROW (the sh exits 1 — the step must redden).
 *
 * Error contract mirrors the sh under `bash -e`: gh failures on the
 * load-bearing calls (pr list) propagate; tolerant calls keep the sh's
 * `|| true` / `|| echo ''` semantics (labels, comment sources, rollup,
 * label create, threads fetch).
 *
 * Env/file contract (the sh step's env block; the JSRunner entry reads
 * jobParams.customParams first, these env names as fallback):
 *   GH_TOKEN            presence gates the skip (gh reads it itself)
 *   NUMBER              the review issue
 *   RUN_OUTPUT          the leg's captured run output (default
 *                       .dmtools/run-output.txt)
 *   MACHINE_AUTHOR      workflow input; .dmtools/config.js knob fallback
 *   MAX_ROUNDS          the auto-rework cap (display + parser env)
 *   GITHUB_REPOSITORY   owner/repo
 *   CONFIG              runner config path (basename → pack agent)
 *   FACTORY_ROOT        legacy verdict parser root
 *   HOME                pack cache root (~/.dmtools/packs/…)
 *
 * Pure functions carry no IO: applyReviewVerdict takes { exec, writeFile,
 * readFile, tempFile, clock, sleepMs, log } capturers (factoryState.js
 * convention). exec results are unwrapped ((res.output || res.stdout) ||
 * res — the #893 review lesson); every interpolation goes through
 * shellQuote (token_usage.js); no global gh is touched (tests stub the
 * transport).
 */

var shellQuote = require('./token_usage.js').shellQuote;

var DEFAULT_RUN_OUTPUT = '.dmtools/run-output.txt';
var CI_POLL_MS = 30000;
var CI_DEADLINE_MS = 600000; // ≤10 min, the sh's SECONDS+600

var RED_CHECKS = 'FAILURE|ERROR|CANCELLED|TIMED_OUT|ACTION_REQUIRED|STARTUP_FAILURE|STALE';
var GREEN_CHECKS = 'SUCCESS|SKIPPED|NEUTRAL';

