            ? opts.runOutput.replace(/[^/]*$/, '') : '/tmp/';
        fallbackPrefix = base + 'rv-' + Date.now() + '-' +
            Math.floor(Math.random() * 10000) + '-';
    }
    return {
        tempFile: function (hint) {
            decide();
            var p = dir ? (dir + '/' + hint) : (fallbackPrefix + hint);
            staged.push(p);
