function applyReviewVerdict(opts, io) {
    opts = opts || {};
    io = io || {};
    var log = io.log || function () {};
    if (!opts.ghToken) {
        log('::warning::SOURCE_GITHUB_TOKEN not set — verdict labels would not trigger workflows; skipping (a maintainer must label manually)');
